/// <summary>
/// Resolves this program's uniform and texture slots against its own reflection.
/// Call once when the program is created - not per frame or per draw - and reuse the
/// result, since slots are stable for the program's lifetime.
/// </summary>
internal readonly struct ImGuiFullbrightParameters
{
    internal ImGuiFullbrightParameters(ShaderReflection reflection)
    {
        Projection = new Float4x4EffectParameter(SlotOf(reflection, "Projection"));
        Texture = new TextureEffectParameter(TextureSlotOf(reflection, "Texture"));
    }

    public Float4x4EffectParameter Projection { get; }
    public TextureEffectParameter Texture { get; }

    // -1 ("not found") mirrors the old FNA model's "parameter != null" check for a
    // uniform the HLSL compiler optimized out - every *EffectParameter.SetValue below
    // no-ops on a negative slot.
    private static int SlotOf(ShaderReflection reflection, string name)
    {
        foreach (var uniform in reflection.Uniforms)
        {
            if (uniform.Name == name) return uniform.Offset;
        }
        return -1;
    }

    private static int TextureSlotOf(ShaderReflection reflection, string name)
    {
        foreach (var texture in reflection.Textures)
        {
            if (texture.Name == name) return texture.Slot;
        }
        return -1;
    }
}

